We say that $u$ is a solution to the problem (\ref{eq})-(\ref{CI})-(\ref{BCD})-(\ref{BCN}) if it verifies:
\begin{equation*}
u \in L^{\infty}(\Omega \times (0,T)),\,\ u-\overline{u} \in L^{2}(0,T;H^{1}_{0}(\Omega))
\end{equation*}
and for all $\psi \in \mathcal{D}(\Omega \times [0,T[)$,
\begin{equation}
\int_{0}^{T}\int_{\Omega}\left( u \, \pa_{t}\psi - \nabla(r(u))\cdot \nabla\psi+ u \, \mathbf{q}\cdot \nabla\psi \right) dx \, dt + \int_{\Omega}u(x,0)\,\psi(x,0)\,dx=0.
\label{defsol}
\end{equation}
\label{defisol}

define the numerical boundary conditions:
\begin{equation}
U^{n+1}_{\sigma}=\frac{1}{\Delta t \, \text{m}(\sigma)}\int_{t^{n}}^{t^{n+1}}\int_{\sigma}\overline{u}(s,t)\,ds \, dt, \quad \sigma \in \mathcal{E}_{ext}^{D}, \,\ n\geq 0.

Let $K \in \mathcal{T}$ and $\sigma \in \mathcal{E}_{K}$. We assume that $dr_{K,\sigma}$ is defined by (\ref{dr2}) in (\ref{sgext}) and that $U_{K}>0$ and $U_{\sigma}>0$. If $d_{\sigma}q_{K,\sigma}=Dh(U)_{K,\sigma}$, then $\mathcal{F}_{K,\sigma}=0$.\\
Indeed, 
\begin{eqnarray*}
\mathcal{F}_{K,\sigma} & = & \tau_{\sigma}dr_{K,\sigma}\left(B\left(-\frac{Dh(U)_{K,\sigma}}{dr_{K,\sigma}}\right)U_{K}-B\left(\frac{Dh(U)_{K,\sigma}}{dr_{K,\sigma}}\right)U_{\sigma}\right)\\
&=& \tau_{\sigma}Dh(U)_{K,\sigma}\left(\frac{\exp\left(\displaystyle{\frac{Dh(U)_{K,\sigma}}{dr_{K,\sigma}}}\right)U_{K}-U_{\sigma}}{\exp\left(\displaystyle{\frac{Dh(U)_{K,\sigma}}{dr_{K,\sigma}}}\right)-1}\right).
\end{eqnarray*}
But using the definition (\ref{defdr}) of $dr$, we obtain
\begin{equation*}
\exp\left(\displaystyle{\frac{Dh(U)_{K,\sigma}}{dr_{K,\sigma}}}\right)=\frac{U_{\sigma}}{U_{K}},
\end{equation*}
and then $ \mathcal{F}_{K,\sigma}=0$. Thus the scheme preserves this type of steady-state.

Let $a$, $b \in \mathbb{R}$, $a,b \geq 0$. Then there exists $\eta \in [\min(a,b),\max(a,b)]$ such that 
\begin{equation*}
dr(a,b)=r'(\eta).
\end{equation*}
\label{propdr}

The result is clear if $ab=0$ or $a=b$. Let us suppose that $ab>0$ and $a < b$ (the proof is the same if $a>b$). If we consider the change of variables $x=\log(a)$ and $y=\log(b)$, we obtain
\begin{equation*}
dr(a,b)=\frac{h(\exp(y))-h(\exp(x))}{y-x}
\end{equation*}
and using Taylor's formula, there exists $\theta \in [x,y]$ such that 
\begin{equation*}
dr(a,b)=\exp(\theta)h'(\exp(\theta))=r'(\exp(\theta)) \text{ (using the definition of $h$). }
\end{equation*}
Finally, there exists $\eta=\exp(\theta) \in [a,b]$ such that 
\begin{equation*}
dr(a,b)=r'(\eta).
\end{equation*}

The flux (\ref{flux}) can also be written as
\begin{equation}
\mathcal{F}_{K,\sigma}^{n+1}=\text{m}(\sigma)q_{K,\sigma}\frac{U_{K}^{n+1}+U^{n+1}_{\sigma}}{2}-\frac{\text{m}(\sigma)q_{K,\sigma}}{2}\coth \left(\frac{d_{\sigma}q_{K,\sigma}}{2dr^{n}_{K,\sigma}}\right)(U^{n+1}_{\sigma}-U^{n+1}_{K}).
\label{flux2}
\end{equation}
The first term is a centred discretization of the convective part. The second term is consistent with the diffusive part of equation (\ref{eq}), since $\displaystyle{\coth(x)\underset{0}{\sim}\frac{1}{x}}$.

Let us assume hypotheses (H1)-(H5). Let $\mathcal{D}$ be an admissible discretization of $\Omega \times (0,T)$. Then there exists a unique solution $\lbrace U_{K}^{n},K \in \mathcal{T},0\leq n \leq N_{T}\rbrace$ to the scheme (\ref{CId})-(\ref{BCd})-(\ref{schemegene})-(\ref{flux}), with $U_{K}^{n} \geq 0$ for all $K \in \mathcal{T}$ and $0\leq n \leq N_{T}$.\\
Moreover, if we suppose that the two following assumptions are fulfilled:
\begin{description}
\item[(H6)] $ \emph{div} (\mathbf{q})=0$,
\item[(H7)] there exist two constants $m>0$ and $M>0$ such that $m\leq \overline{u},u_{0}\leq M$,
\end{description}
then we have
\begin{equation}
0 <m \leq U^{n}_{K} \leq M, \quad \forall K \in \mathcal{T}, \quad \forall n \geq 0.
\label{estimlinf}
\end{equation}

At each time step, the scheme (\ref{CId})-(\ref{BCd})-(\ref{schemegene})-(\ref{flux}) leads to a system of card$(\mathcal{T})$ linear equations on $U^{n+1}=(U^{n+1}_{K})_{K \in \mathcal{T}}$ which can be written:
\begin{equation*}
A^{n}U^{n+1}=S^{n},
\end{equation*}
where :
\begin{itemize}
\item[$\bullet$] $A^{n}$ is the matrix defined by
\begin{alignat*}{3}
&A^{n}_{K,K} & = &  \frac{\text{m}(K)}{\Delta t}+\sum_{\sigma \in \mathcal{E}_{K}}\tau_{\sigma}dr^{n}_{K,\sigma}B\left(\frac{-d_{\sigma}q_{K,\sigma}}{dr^{n}_{K,\sigma}}\right) \,\ \forall K \in \mathcal{T},\\
&A^{n}_{K,L} & = & -\tau_{\sigma}dr^{n}_{K,\sigma}B\left(\frac{d_{\sigma}q_{K,\sigma}}{dr^{n}_{K,\sigma}}\right) \,\ \forall L \in \mathcal{T} \text{ such that } \sigma=K|L \in \mathcal{E}_{int,K};
\end{alignat*}
\item[$\bullet$] $\displaystyle{S^{n}=\left(\frac{\text{m}(K)}{\Delta t}U^{n}_{K}\right)_{K \in \mathcal{T}}+Tb^{n}}$, with
\begin{equation*}
Tb^{n}_{K} = \left\{\begin{array}{ll} 0  & \text{ if } K \in \mathcal{T} \text{ such that } \text{m}(\pa K\cap \Gamma)=0,\\ \displaystyle{\sum_{\sigma \in \mathcal{E}_{ext,K}^{D}}\tau_{\sigma}dr^{n}_{K,\sigma}B\left(\displaystyle{\frac{d_{\sigma}q_{K,\sigma}}{dr^{n}_{K,\sigma}}}\right)U^{n+1}_{\sigma}}  & \text{ if } K \in \mathcal{T} \text{ such that } \text{m}(\pa K\cap \Gamma)\neq 0. \end{array}\right.
\end{equation*}
\end{itemize}
The diagonal terms of $A^{n}$ are positive and the offdiagonal terms are nonnegative (since $B(x)>0$ for all $x \in \mathbb{R}$ and $dr^{n}_{K,\sigma} \geq 0$ for all $K \in \mathcal{T}$, for all $\sigma \in \mathcal{E}_{K}$). Moreover, since $dr^{n}_{K,\sigma}=dr_{L,\sigma}^{n}$ and $q_{K,\sigma}=-q_{L,\sigma}$ for all $ \sigma=K|L \in \mathcal{E}_{int}$, we have for all $L \in \mathcal{T}$:
\begin{equation*}
\left|A^{n}_{L,L}\right|-\sum_{\substack{K \in \mathcal{T} \\ K \neq L}}\left|A^{n}_{K,L}\right|=\frac{\text{m}(L)}{\Delta t}>0,
\end{equation*}
and then $A^{n}$ is strictly diagonally dominant with respect to the columns. $A^{n}$ is then an M-matrix so $A^{n}$ is invertible, which gives existence and uniqueness of the solution of the scheme. Moreover, $(A^{n})^{-1}\geq 0$ and since $U_{K}^{0} \geq 0$ for all $K\in \mathcal{T}$ (using (H3)) and $U^{n+1}_{\sigma} \geq 0$ for all $n \geq 0$, for all $\sigma \in \mathcal{E}_{ext}^{D}$ (using (H2)), it is easy to prove by induction that $U^{n}_{K} \geq 0$ for all $K \in \mathcal{T}$, for all $n \geq 0$.\\
Now, we suppose that (H6) and (H7) are fulfilled. We prove that $U^{n}_{K}\leq M $ for all $K \in \mathcal{T}$, for all $n \geq 0$ by induction. Thanks to hypothesis (H7), we have clearly $U^{0}_{K}\leq M $ for all $ K \in \mathcal{T}$.\\
Let us suppose that $U^{n}_{K}\leq M \quad \forall K \in \mathcal{T}$. We want to prove $U^{n+1}_{K}\leq M \quad \forall K \in \mathcal{T}$.\\
Let us define $\textbf{M}=(M,...,M)^{T} \in \mathbb{R}^{\text{card}(\mathcal{T})}$. Since $A^{n}$ is an M-matrix, we have $(A^{n})^{-1} \geq 0$ and then it suffices to prove that $A^{n}\left(U^{n+1}-\textbf{M}\right) \leq 0$. \\
We first compute $A^{n}\textbf{M}$. Using the following property of the Bernoulli function:
\begin{equation}
B(x)-B(-x)=-x \quad \forall x \in \mathbb{R},
\label{propriB}
\end{equation}
we obtain that for all $K \in \mathcal{T}$,
\begin{equation*}
\left(A^{n}\textbf{M}\right)_{K}=M\left(\frac{\text{m}(K)}{\Delta t}+\sum_{\sigma \in \mathcal{E}_{int,K}}\text{m}(\sigma)q_{K,\sigma}+\sum_{\sigma \in \mathcal{E}_{ext,K}^{D}}\tau_{\sigma}dr^{n}_{K,\sigma}B\left(-\frac{d_{\sigma}q_{K,\sigma}}{dr^{n}_{K,\sigma}}\right)\right).
\end{equation*}
Then we compute $A^{n}\left(U^{n+1}-\textbf{M}\right)$: for all $K \in \mathcal{T}$
\begin{eqnarray*}
\left(A^{n}\left(U^{n+1}-\textbf{M}\right)\right)_{K} &=& \frac{\text{m}(K)}{\Delta t}(U^{n}_{K}-M)+ \sum_{\sigma \in \mathcal{E}_{ext,K}^{D}}\tau_{\sigma}dr^{n}_{K,\sigma}B\left(\frac{d_{\sigma}q_{K,\sigma}}{dr^{n}_{K,\sigma}}\right)U^{n+1}_{\sigma} \\
& & -M \sum_{\sigma \in \mathcal{E}_{int,K}}\text{m}(\sigma)q_{K,\sigma}-M\sum_{\sigma \in \mathcal{E}_{ext,K}^{D}}\tau_{\sigma}dr^{n}_{K,\sigma}B\left(-\frac{d_{\sigma}q_{K,\sigma}}{dr^{n}_{K,\sigma}}\right).
\end{eqnarray*}
By induction hypothesis, the first term is nonpositive. Moreover, using hypothesis (H7) and the property (\ref{propriB}), we obtain
\begin{eqnarray*}
\left(A^{n}\left(U^{n+1}-\textbf{M}\right)\right)_{K} &\leq &-M \sum_{\sigma \in \mathcal{E}_{int,K}}\text{m}(\sigma)q_{K,\sigma} -M \sum_{\sigma \in \mathcal{E}_{ext,K}^{D}}\text{m}(\sigma)q_{K,\sigma}\\
&\leq & -M \sum_{\sigma \in \mathcal{E}_{K}}\text{m}(\sigma)q_{K,\sigma}.
\end{eqnarray*}
However, using hypothesis (H6) and the definition of $q_{K,\sigma}$ (\ref{q}), we get
\begin{equation*}
\sum_{\sigma \in \mathcal{E}_{K}}\text{m}(\sigma)q_{K,\sigma}=\sum_{\sigma \in \mathcal{E}_{K}}\int_{\sigma}q \cdot \mathbf{n}_{K,\sigma}\, ds= \int_{K}\text{div}(q)=0,
\end{equation*}
and then $\left(A^{n}\left(U^{n+1}-\textbf{M}\right)\right)_{K} \leq 0$ for all $K \in \mathcal{T}$.\\
So we have $A^{n}\left(U^{n+1}-\textbf{M}\right) \leq 0$, therefore we deduce that $U^{n+1}-\textbf{M} \leq 0$, hence $U^{n+1}_{K} \leq M \quad \forall K$ and we can show by the same way that $U^{n+1}_{K} \geq m \quad \forall K$.

In the case of the drift-diffusion system for semiconductors, the hypothesis (H6) is not fulfilled ($ \Delta V \neq 0$). Nevertheless, if we assume that
\begin{itemize}
\item the doping profile $C$ is equal to $0$,
\item there exist two constants $m>0$ and $M>0$ such that $m\leq \overline{N},N_{0},\overline{P},P_{0}\leq M$,
\item $M \Delta t \leq 1$,
\end{itemize}
then we have, using the same kind of proof as in \cite{Chainais-Hillairet2003},
\begin{eqnarray*}
0 <m \leq N^{n}_{K} \leq M, & &\quad \forall K \in \mathcal{T}, \quad \forall n \geq 0,\\
0 <m \leq P^{n}_{K} \leq M, & &\quad \forall K \in \mathcal{T}, \quad \forall n \geq 0.
\end{eqnarray*}

Let $ \mathcal{D}$ be an admissible discretization of $ \Omega \times (0,T)$. The approximate solution to the problem (\ref{eq})-(\ref{CI})-(\ref{BCD})-(\ref{BCN}) associated to the discretization $\mathcal{D}$ is defined as piecewise constant function by:
\begin{equation}
u_{\delta}(x,t) =  U^{n+1}_{K},  \quad \forall(x,t)\in K\times[t^{n},t^{n+1}[, \label{defiuapp}
\end{equation}
where $ \lbrace U^{n}_{K},K \in \mathcal{T},0\leq n \leq N_{T}\rbrace $ is the unique solution to the scheme (\ref{CId})-(\ref{BCd})-(\ref{schemegene})-(\ref{flux}).

\label{propestiml2}
Let assume (H1)-(H7) are satisfied. Let $u_{\delta}$ be defined by the scheme (\ref{CId})-(\ref{BCd})-(\ref{schemegene})-(\ref{flux}) and (\ref{defiuapp}).\\
There exists $D_{1}>0$ only depending on $r$, $\textbf{q}$, $u_{0}$, $\overline{u}$, $\Omega$ and $T$ such that
\begin{equation}
\Vert u_{\delta} \Vert_{1,\mathcal{D}}^{2} \leq D_{1}.
\label{estiml2}
\end{equation}

We follow the proof of Lemma 4.2 in \cite{Eymard2006}. Throughout this proof, $D_{i}$ denotes constants which depend only on $r$, $\textbf{q}$, $u_{0}$, $\overline{u}$, $\Omega$ and $T$. We set
\begin{equation*}
\overline{U}^{n+1}_{K}=\displaystyle{\frac{1}{\Delta t\text{m}(K)}\int_{t^{n}}^{t^{n+1}}\int_{K}\overline{u}(x,t)\, dx \, dt},\, \forall K \in \mathcal{T}, \,\ \forall n \in \mathbb{N},
\end{equation*} 
and
\begin{equation*}
w^{n+1}_{K}=U^{n+1}_{K}-\overline{U}^{n+1}_{K},\, \forall K \in \mathcal{T}, \,\ \forall n \in \mathbb{N}.
\end{equation*}
We multiply the scheme (\ref{schemegene}) by $\Delta t w^{n+1}_{K}$ and we sum over $n$ and $K$. We obtain $A+B=0$, where: 
\begin{eqnarray*}
A &=& \sum_{n=0}^{N_{T}}\sum_{K \in \mathcal{T}}\text{m}(K)\left(U^{n+1}_{K}-U^{n}_{K}\right)w_{K}^{n+1},\\
B &=& \sum_{n=0}^{N_{T}} \Delta t \sum_{K \in \mathcal{T}} \sum_{\sigma \in \mathcal{E}_{K}} \mathcal{F}^{n+1}_{K,\sigma}w^{n+1}_{K}.
\end{eqnarray*}

\textbf{Estimate of $A$.} This term is treated in \cite{Eymard2006}. We get:
\begin{equation}
A \geq -\frac{1}{2}\Vert u_{0}-\overline{u}(.,0)\Vert_{L^{2}(\Omega)}^{2}-2\Vert \pa_{t}\overline{u}\Vert_{L^{1}(\Omega \times (0,T))}|M-m| =-D_{2}. \label{estimA}
\end{equation}

\textbf{Estimate of $B$.} A discrete integration by parts yields (using that $w_{\sigma}^{n+1}=0$ for all $\sigma \in \mathcal{E}_{ext}^{D}$ and for all $n \geq 0$):

\begin{equation*}
B = \sum_{n=0}^{N_{T}} \Delta t \sum_{\substack{\sigma \in \mathcal{E}_{int} \\ \sigma=K|L}} \mathcal{F}^{n+1}_{K,\sigma}\left(w^{n+1}_{K}-w_{L}^{n+1}\right) + \sum_{n=0}^{N_{T}} \Delta t \sum_{K \in \mathcal{T}} \sum_{\sigma \in \mathcal{E}_{ext,K}^{D}} \mathcal{F}^{n+1}_{K,\sigma} \left(w^{n+1}_{K}-w_{\sigma}^{n+1}\right),
\end{equation*}
which delivers $B=B'-\overline{B}$, with:
\begin{eqnarray*}
B' &=& \sum_{n=0}^{N_{T}} \Delta t \sum_{\substack{\sigma \in \mathcal{E}_{int} \\ \sigma=K|L}} \mathcal{F}^{n+1}_{K,\sigma}\left(U^{n+1}_{K}-U_{L}^{n+1}\right) + \sum_{n=0}^{N_{T}} \Delta t \sum_{K \in \mathcal{T}} \sum_{\sigma \in \mathcal{E}_{ext,K}^{D}} \mathcal{F}^{n+1}_{K,\sigma}\left(U^{n+1}_{K}-U_{\sigma}^{n+1}\right),\\
\overline{B} &=& \sum_{n=0}^{N_{T}} \Delta t \sum_{\substack{\sigma \in \mathcal{E}_{int} \\ \sigma=K|L}} \mathcal{F}^{n+1}_{K,\sigma}\left(\overline{U}^{n+1}_{K}-\overline{U}_{L}^{n+1}\right) + \sum_{n=0}^{N_{T}} \Delta t \sum_{K \in \mathcal{T}} \sum_{\sigma \in \mathcal{E}_{ext,K}^{D}} \mathcal{F}^{n+1}_{K,\sigma}\left(\overline{U}^{n+1}_{K}-\overline{U}_{\sigma}^{n+1}\right).
\end{eqnarray*}

\textbf{Estimate of $\overline{B}$.} Using the expression (\ref{flux2}) of $\mathcal{F}_{K,\sigma}^{n+1}$, we have $\overline{B}=\overline{B}_{1}+\overline{B}_{2}$ with
\begin{eqnarray*}
\overline{B}_{1}&=& \sum_{n=0}^{N_{T}} \Delta t \sum_{\substack{\sigma \in \mathcal{E}_{int} \\ \sigma=K|L}} \frac{\text{m}(\sigma)q_{K,\sigma}}{2}\left(U_{K}^{n+1}+U_{L}^{n+1}\right)\left(\overline{U}_{K}^{n+1}-\overline{U}_{L}^{n+1}\right) \\
& & + \sum_{n=0}^{N_{T}} \Delta t \sum_{K \in \mathcal{T}} \sum_{\sigma \in \mathcal{E}_{ext,K}^{D}}\frac{\text{m}(\sigma)q_{K,\sigma}}{2}\left(U_{K}^{n+1}+U_{\sigma}^{n+1}\right)\left(\overline{U}_{K}^{n+1}-\overline{U}_{\sigma}^{n+1}\right),\\
\overline{B}_{2}&=& \sum_{n=0}^{N_{T}} \Delta t \sum_{\substack{\sigma \in \mathcal{E}_{int} \\ \sigma=K|L}} \frac{\text{m}(\sigma)q_{K,\sigma}}{2}\coth\left(\frac{d_{\sigma}q_{K,\sigma}}{2dr^{n}_{K,\sigma}}\right)\left(U_{K}^{n+1}-U_{L}^{n+1}\right)\left(\overline{U}_{K}^{n+1}-\overline{U}_{L}^{n+1}\right)\\
& & + \sum_{n=0}^{N_{T}} \Delta t \sum_{K \in \mathcal{T}} \sum_{\sigma \in \mathcal{E}_{ext,K}^{D}}\frac{\text{m}(\sigma)q_{K,\sigma}}{2}\coth\left(\frac{d_{\sigma}q_{K,\sigma}}{2dr^{n}_{K,\sigma}}\right)\left(U_{K}^{n+1}-U_{\sigma}^{n+1}\right)\left(\overline{U}_{K}^{n+1}-\overline{U}_{\sigma}^{n+1}\right).
\end{eqnarray*}
The term $\overline{B}_{1}$ is treated like in \cite{Eymard2006}, which leads to
\begin{equation*}
\vert \overline{B}_{1} \vert \leq M \Vert \textbf{q} \Vert_{\infty}\Vert \overline{u}_{\delta} \Vert_{1,\mathcal{D}}\text{dm}(\Omega)=D_{3}.
\end{equation*}
We apply Young's inequality for $\overline{B}_{2}$: for any $\alpha>0$, we have
\begin{eqnarray*}
\left\vert \overline{B}_{2} \right\vert &\leq &\frac{\alpha}{2} \sum_{n=0}^{N_{T}} \Delta t \sum_{\substack{\sigma \in \mathcal{E}_{int} \\ \sigma=K|L}} \tau_{\sigma}\left(dr_{K,\sigma}^{n}\right)^{2}\left(\frac{d_{\sigma}q_{K,\sigma}}{2dr_{K,\sigma}^{n}}\coth\left(\frac{d_{\sigma}q_{K,\sigma}}{2dr^{n}_{K,\sigma}}\right)\right)^{2}\left(U_{K}^{n+1}-U_{L}^{n+1}\right)^{2}\\
& & + \frac{\alpha}{2} \sum_{n=0}^{N_{T}} \Delta t \sum_{K \in \mathcal{T}} \sum_{\sigma \in \mathcal{E}_{ext,K}^{D}} \tau_{\sigma}\left(dr_{K,\sigma}^{n}\right)^{2} \left(\frac{d_{\sigma}q_{K,\sigma}}{2dr^{n}_{K,\sigma}}\coth\left(\frac{d_{\sigma}q_{K,\sigma}}{2dr^{n}_{K,\sigma}}\right)\right)^{2}\left(U_{K}^{n+1}-U_{\sigma}^{n+1}\right)^{2}\\
& &+ \frac{1}{2\alpha}\Vert \overline{u}_{\delta}\Vert_{1,\mathcal{D}}^{2}. 
\end{eqnarray*}
By the hypothesis (H4), we have $\displaystyle{\inf_{s \in [m,M]}r'(s)>0}$. Then, using Lemma \ref{propdr}, the $L^{\infty}$ estimate on $u_{\delta}$ (\ref{estimlinf}) and the hypothesis (H5), we have
\begin{equation*}
\frac{d_{\sigma}q_{K,\sigma}}{2dr^{n}_{K,\sigma}} \leq \frac{\Vert \textbf{q} \Vert_{\infty}\text{diam}(\Omega)}{\displaystyle{\inf_{s\in [m,M]}r'(s)}}, \, \forall n \in \mathbb{N},\, \forall K \in \mathcal{T}, \, \forall \sigma \in \mathcal{E}_{K}. 
\end{equation*}
Moreover, since $x \mapsto x \coth(x)$ is continuous on $\mathbb{R}$, we obtain
\begin{equation*}
\left(\frac{d_{\sigma}q_{K,\sigma}}{2dr^{n}_{K,\sigma}}\coth\left(\frac{d_{\sigma}q_{K,\sigma}}{2dr^{n}_{K,\sigma}}\right)\right)^{2} \leq D_{4}, \, \forall n \in \mathbb{N},\, \forall K \in \mathcal{T}, \, \forall \sigma \in \mathcal{E}_{K}. 
\end{equation*}
Thus we can bound $ \overline{B}$:
\begin{equation}
\left\vert \overline{B} \right\vert \leq D_{3}+\frac{\alpha}{2}D_{4}\left(\sup_{s \in [m,M]}r'(s)\right)^{2}\Vert u_{\delta} \Vert_{1,\mathcal{D}}^{2}+\frac{1}{2\alpha}\Vert \overline{u}_{\delta} \Vert_{1,\mathcal{D}}.
\label{estimBb} 
\end{equation} 

\textbf{Estimate of $B'$.} First, using the expression (\ref{flux2}) of the flux and Lemma \ref{propdr}, we have for all $n \geq 0$, for all $K \in \mathcal{T}$ and for all $\sigma=K|L \in \mathcal{E}_{int,K}$
\begin{eqnarray*}
\mathcal{F}^{n+1}_{K,\sigma}\left(U^{n+1}_{K}-U^{n+1}_{L}\right) &=& \frac{\text{m}(\sigma)q_{K,\sigma}}{2}\left(\left(U_{K}^{n+1}\right)^{2}-\left(U^{n+1}_{L}\right)^{2}\right)\\
& & + \tau_{\sigma} r'(\eta_{K,\sigma}^{n})\frac{d_{\sigma}q_{K,\sigma}}{2r'(\eta_{K,\sigma}^{n})} \coth\left(\frac{d_{\sigma}q_{K,\sigma}}{2r'(\eta_{K,\sigma}^{n})}\right)\left(U^{n+1}_{K}-U^{n+1}_{L}\right)^{2}.
\end{eqnarray*}  
Then, since $x\coth(x) \geq 1$ for all $x\in \mathbb{R}$, we get:
\begin{equation*}
\mathcal{F}^{n+1}_{K,\sigma}\left(U^{n+1}_{K}-U^{n+1}_{L}\right) \geq  \frac{\text{m}(\sigma)q_{K,\sigma}}{2}\left(\left(U_{K}^{n+1}\right)^{2}-\left(U^{n+1}_{L}\right)^{2}\right) + \tau_{\sigma}\inf_{s \in [m,M]}r'(s) \left(U^{n+1}_{K}-U^{n+1}_{L}\right)^{2}.
\end{equation*}
We obtain the same type of inequality for $\mathcal{F}^{n+1}_{K,\sigma}\left(U^{n+1}_{K}-U^{n+1}_{\sigma}\right)$. Thus we get 
\begin{eqnarray*}
B' &\geq & \inf_{s \in [m,M]}r'(s)\Vert u_{\delta}\Vert_{1,\mathcal{D}}^{2}+\sum_{n=0}^{N_{T}}\Delta t\sum_{\substack{\sigma \in \mathcal{E}_{int} \\ \sigma=K|L}} \frac{\text{m}(\sigma)q_{K,\sigma}}{2}\left(\left(U_{K}^{n+1}\right)^{2}-\left(U^{n+1}_{L}\right)^{2}\right)\\
& &+\sum_{n=0}^{N_{T}}\Delta t\sum_{K\in \mathcal{T}}\sum_{\sigma \in \mathcal{E}_{ext,K}^{D}}\frac{\text{m}(\sigma)q_{K,\sigma}}{2}\left(\left(U_{K}^{n+1}\right)^{2}-\left(U^{n+1}_{\sigma}\right)^{2}\right).
\end{eqnarray*}
Through integrating by parts and using the hypothesis (H6), we get
\begin{eqnarray*}
& &\sum_{n=0}^{N_{T}}\Delta t\sum_{\substack{\sigma \in \mathcal{E}_{int} \\ \sigma=K|L}} \frac{\text{m}(\sigma)q_{K,\sigma}}{2}\left(\left(U_{K}^{n+1}\right)^{2}-\left(U^{n+1}_{L}\right)^{2}\right)\\
&+&\sum_{n=0}^{N_{T}}\Delta t\sum_{K\in \mathcal{T}}\sum_{\sigma \in \mathcal{E}_{ext,K}^{D}}\frac{\text{m}(\sigma)q_{K,\sigma}}{2}\left(\left(U_{K}^{n+1}\right)^{2}-\left(U^{n+1}_{\sigma}\right)^{2}\right) \\
& = & -\sum_{n=0}^{N_{T}}\Delta t \sum_{K\in \mathcal{T}}\sum_{\sigma \in \mathcal{E}_{ext,K}^{D}} \frac{1}{2}\int_{\sigma}\textbf{q}(x)\cdot \textbf{n}_{K,\sigma}\, ds(x) \left(U_{\sigma}^{n+1}\right)^{2}=-D_{5},
\end{eqnarray*}
and then 
\begin{equation}
B' \geq \inf_{s \in [m,M]}r'(s)\Vert u_{\delta}\Vert_{1,\mathcal{D}}^{2}-D_{5}.
\label{estimBp}
\end{equation}


\textbf{Conclusion.} Using $A+B=0$ and estimates (\ref{estimA}), (\ref{estimBb}) and (\ref{estimBp}), we finally get for any $\alpha>0$:
\begin{equation*}
\left(\inf_{s\in [m,M]}r'(s)-\frac{\alpha}{2}D_{4}\left(\sup_{s\in [m,M]}r'(s)\right)^{2}\right)\Vert u_{\delta}\Vert_{1,\mathcal{D}}^{2} \leq D_{2}+D_{3}+D_{5}+\frac{1}{2\alpha}\Vert \overline{u}_{\delta}\Vert_{1,\mathcal{D}}^{2},
\end{equation*}
thus for $\alpha < \displaystyle{\frac{2\displaystyle{\inf_{s\in [m,M]}r'(s)}}{D_{4}\left(\displaystyle{\sup_{s\in [m,M]}r'(s)}\right)^{2}}}$, we obtain $
\Vert u_{\delta} \Vert_{1,\mathcal{D}}^{2} \leq D_{1}$.

We suppose (H1)-(H7). Let $\mathcal{D}$ be an admissible discretization of $ \Omega \times (0,T)$. Let $u_{\delta}$ be defined by the scheme (\ref{CId})-(\ref{BCd})-(\ref{schemegene})-(\ref{flux}) and by (\ref{defiuapp}).\\
Let $ \hat{u}$ be defined by $\hat{u}_{\delta}=u_{\delta} \text{ a.e. on } \Omega \times (0,T)$ and $\hat{u}_{\delta}=0 \text{ a.e. on } \mathbb{R}^{d+1} \setminus \Omega \times (0,T)$.\\
Then we get the existence of $M_{2}>0$, only depending on $ \Omega$, $T$, $r$, $q$, $u_{0}$, $\overline{u}$ and not on $ \mathcal{D}$ such that 
\begin{equation}
\int_{0}^{T}\int_{\Omega}\left(\hat{u}_{\delta}(x+\eta,t)-\hat{u}_{\delta}(x,t)\right)^{2}\, dx\, dt \leq M_{2}|\eta|(|\eta|+4\delta), \quad \forall \eta \in \mathbb{R}^{d},
\label{transspace}
\end{equation}
and
\begin{equation}
\int_{0}^{T}\int_{\Omega}\left(\hat{u}_{\delta}(x,t+\tau)-\hat{u}_{\delta}(x,t)\right)^{2}\, dx \, dt \leq M_{2}|\tau|, \quad \forall \tau \in \mathbb{R}.
\label{transtime}
\end{equation}

We suppose (H1)-(H7). \\
There exist subsequences of $(u_{\delta})_{\delta>0}$ and $(\nabla^{\delta}u_{\delta})_{\delta>0}$, still denoted $(u_{\delta})_{\delta>0}$ and $(\nabla^{\delta}u_{\delta})_{\delta>0}$, and a function $u \in L^{\infty}(0,T;H^{1}(\Omega))$ such that
\begin{equation*}
\begin{array}{cll} u_{\delta} \rightarrow  u & \text{ in } L^{2}(\Omega \times ]0,T[) \text{ strongly,} & \text{ as } \delta \rightarrow 0, \\
\nabla^{\delta}u_{\delta} \rightharpoonup \nabla u & \text{ in } (L^{2}(\Omega \times ]0,T[))^{d} \text{ weakly,} & \text{ as } \delta \rightarrow 0. \end{array}
\end{equation*}
\label{compaciteu}

Let $\psi \in \mathcal{D}(\Omega \times [0,T[)$ be a test function and $\psi^{n}_{K}=\psi(x_{K},t^{n})$ for all $K \in \mathcal{T}$ and $n \geq 0$. We suppose that $\delta >0$ is small enough such that Supp$(\psi) \subset \lbrace x \in \Omega; \text{ d}(x,\Gamma)>\delta \rbrace \times [0,(N_{T}-1)\Delta t[$. Let us define an approximate gradient of $\psi$ by
\begin{equation*}
\nabla^{\delta}\psi(x,t)=\left\{\begin{array}{lcl} \displaystyle{\frac{\text{m}(\sigma)}{\text{m}(T_{K,\sigma})}\left(\psi^{n}_{L}-\psi^{n}_{K}\right) \mathbf{n}_{K,\sigma}} &  & \text{ if }  (x,t) \in T_{K,\sigma}\times [t^{n},t^{n+1}[,\,\ \sigma=K|L, \\ \displaystyle{\frac{\text{m}(\sigma)}{\text{m}(T_{K,\sigma})}\left(\psi_{\sigma}^{n}-\psi^{n}_{K}\right) \mathbf{n}_{K,\sigma}} & & \text{ if }  (x,t) \in T_{K,\sigma}\times [t^{n},t^{n+1}[, \,\ \sigma \in \mathcal{E}_{ext,K}. \end{array}\right.
\end{equation*}
We get from \cite{Eymard2003} that $(\nabla^{\delta}\psi)_{\delta>0}$ weakly converges to $\nabla \psi$ in $(L^{2}(\Omega \times (0,T)))^{d}$ as $\delta$ goes to zero.\\
Let us introduce the following notations:
\begin{eqnarray*}
B_{10}(\delta) &=& -\left(\int_{0}^{T}\int_{\Omega}\ud(x,t)\,\pa_{t}\psi(x,t)\, dx \, dt+\int_{\Omega}\ud(x,0)\, \psi(x,0) \, dx\right),\\
B_{20}(\delta) &=& \int_{0}^{T}\int_{\Omega}r'(u_{\delta}(x,t-\Delta t))\, \nabla^{\delta}u_{\delta}(x,t)\cdot \nabla\psi(x,t)\, dx \, dt,\\
B_{30}(\delta) &=& -\int_{0}^{T}\int_{\Omega} \ud(x,t)\, \mathbf{q}(x) \cdot \nabla^{\delta}\psi(x,t)\, dx \, dt,
\end{eqnarray*}
and
\begin{equation*}
\varepsilon(\delta)=-B_{10}(\delta)-B_{20}(\delta)-B_{30}(\delta).
\end{equation*}
Multiplying the scheme (\ref{schemegene}) by $\Delta t \psi^{n}_{K}$ and summing through $K$ and $n$, we obtain
\begin{equation*}
B_{1}(\delta)+B_{2}(\delta)+B_{3}(\delta)=0,
\end{equation*}
where
\begin{eqnarray*}
B_{1}(\delta) &=& \sum_{n=0}^{N_{T}}\sum_{K \in \mathcal{T}}\text{m}(K)\left(U_{K}^{n+1}-U_{K}^{n}\right)\psi^{n}_{K},\\
B_{2}(\delta) &=& -\sum_{n=0}^{N_{T}}\Delta t \sum_{K \in \mathcal{T}} \sum_{\sigma \in \mathcal{E}_{K}}\frac{\text{m}(\sigma)q_{K,\sigma}}{2}\coth\left(\frac{d_{\sigma}q_{K,\sigma}}{2dr_{K,\sigma}^{n}}\right)\left(U^{n+1}_{\sigma}-U^{n+1}_{K}\right)\psi^{n}_{K},\\
B_{3}(\delta) &=& \sum_{n=0}^{N_{T}}\Delta t \sum_{K \in \mathcal{T}} \sum_{\sigma \in \mathcal{E}_{K}} \text{m}(\sigma)q_{K,\sigma}\frac{U_{K}^{n+1}+U_{\sigma}^{n+1}}{2}\psi^{n}_{K}.
\end{eqnarray*}
From the strong convergence of the sequence $(\ud)_{\delta>0}$ to $u$ in $L^{2}(\Omega \times ]0,T[)$, it is clear using the time translate estimate (\ref{transtime}) that there exists a subsequence of $(\ud)_{\delta>0}$, still denoted by   $(\ud)_{\delta>0}$, such that
\begin{equation*}
\ud( \,\cdot \, ,\, \cdot \,-\Delta t) \longrightarrow u \text{ in } L^{2}(\Omega \times ]0,T[) \text{ strongly as } \delta \rightarrow 0,
\end{equation*}
where $u \in L^{\infty}(0,T;H^{1}(\Omega))$ is defined in Proposition \ref{compaciteu}. Moreover, thanks to hypothesis (H4), we have $r' \in \mathcal{C}^{1}(\mathbb{R})$, and using the $L^{\infty}$-estimate (\ref{estimlinf}) we obtain that
\begin{equation*}
r'(\ud(\,\cdot \, ,\, \cdot \,-\Delta t))\longrightarrow r'(u) \text{ in } L^{2}(\Omega \times ]0,T[) \text{ strongly as } \delta \rightarrow 0.
\end{equation*}
Finally using this strong convergence and the weak convergence of the sequences $(\nabla^{\delta}u_{\delta})_{\delta>0}$ to $\nabla u$ and $(\nabla^{\delta}\psi)_{\delta>0}$ to $\nabla \psi$ in $(L^{2}(\Omega \times ]0,T[))^{d}$, it is easy to see that
\begin{eqnarray*}
\varepsilon(\delta)& \longrightarrow & \int_{0}^{T}\int_{\Omega}\left(u(x,t)\, \pa_{t}\psi-r'(u(x,t))\, \nabla u(x,t) \cdot \nabla \psi+u(x,t) \, \mathbf{q}(x) \cdot \nabla\psi\right) \, dx \, dt\\
& & +\int_{\Omega}u(x,0) \, \psi(x,0)\, dx, \text{ as } \delta \rightarrow 0.
\end{eqnarray*}
Therefore, it suffices to prove that $\varepsilon(\delta) \longrightarrow 0$ as $\delta \rightarrow 0$ and to this end we are going to prove that $\varepsilon(\delta)+B_{1}(\delta)+B_{2}(\delta)+B_{3}(\delta) \longrightarrow 0$ as $\delta \rightarrow 0$.\\

\textbf{Estimate of $B_{1}(\delta)-B_{10}(\delta)$.} This term is discussed for example in \cite{Chainais-Hillairet2003} (Theorem 5.2) and it is proved that:
\begin{equation*}
|B_{1}(\delta)-B_{10}(\delta)| \leq  \left[(T+1)\text{m}(\Omega)M\Vert \psi \Vert_{\mathcal{C}^{2}(\Omega \times (0,T))}\right]\delta \longrightarrow 0 \text{ as } \delta \rightarrow 0.
\end{equation*}

\textbf{Estimate of $B_{2}(\delta)-B_{20}(\delta)$.} Using a discrete integration by parts, we write
\begin{equation*}
B_{2}(\delta) = \sum_{n=0}^{N_{T}}\Delta t \sum_{\substack{\sigma \in \mathcal{E}_{int} \\ \sigma=K|L}}\frac{\text{m}(\sigma)q_{K,\sigma}}{2}\coth\left(\frac{d_{\sigma} q_{K,\sigma}}{2 dr^{n}_{K,\sigma}}\right)\left(U^{n+1}_{L}-U^{n+1}_{K}\right)(\psi_{L}^{n}-\psi_{K}^{n}).
\end{equation*}
Then we rewrite $B_{2}(\delta)=B_{21}(\delta)+B_{22}(\delta)+B_{23}(\delta)$, with
\begin{eqnarray*}
B_{21}(\delta) &=& \sum_{n=0}^{N_{T}}\Delta t \sum_{\substack{\sigma \in \mathcal{E}_{int} \\ \sigma=K|L}} \tau_{\sigma}r'(U^{n}_{K})\left(U^{n+1}_{L}-U^{n+1}_{K}\right)(\psi_{L}^{n}-\psi_{K}^{n}),\\
B_{22}(\delta) &=& \sum_{n=0}^{N_{T}}\Delta t \sum_{\substack{\sigma \in \mathcal{E}_{int} \\ \sigma=K|L}}\tau_{\sigma}\left(\frac{d_{\sigma}q_{K,\sigma}}{2dr^{n}_{K,\sigma}}\coth\left(\frac{d_{\sigma}q_{K,\sigma}}{2dr^{n}_{K,\sigma}}\right)-1\right)dr^{n}_{K,\sigma}\left(U^{n+1}_{L}-U^{n+1}_{K}\right)(\psi_{L}^{n}-\psi_{K}^{n}),\\
B_{23}(\delta) &=& \sum_{n=0}^{N_{T}}\Delta t \sum_{\substack{\sigma \in \mathcal{E}_{int} \\ \sigma=K|L}}\tau_{\sigma}\left(dr^{n}_{K,\sigma}-r'(U^{n}_{K})\right)\left(U^{n+1}_{L}-U^{n+1}_{K}\right)\left(\psi_{L}^{n}-\psi_{K}^{n}\right).
\end{eqnarray*}

Using the definition of $\tilde{u}_{\delta}$ and $\nabla^{\delta}u_{\delta}$, we rewrite $B_{20}(\delta)$ as $B_{210}(\delta)+B_{220}(\delta)$ with:
\begin{eqnarray*}
B_{210}(\delta) &=& \sum_{n=0}^{N_{T}}\sum_{\substack{\sigma \in \mathcal{E}_{int} \\ \sigma=K|L}}r'(U_{K}^{n})\frac{\text{m}(\sigma)}{\text{m}(T_{K,\sigma})}\left(U_{L}^{n+1}-U_{K}^{n+1}\right)\int_{t^{n}}^{t^{n+1}}\int_{T_{K,\sigma}}\nabla \psi(x,t) \cdot \mathbf{n}_{K,\sigma}\, dx \, dt,\\
B_{220}(\delta) &=& \sum_{n=0}^{N_{T}}\sum_{\substack{\sigma \in \mathcal{E}_{int} \\ \sigma=K|L}}\!\!\!\! \left(r'(U^{n}_{L})-r'(U^{n}_{K})\right)\frac{\text{m}(\sigma)}{\text{m}(T_{K,\sigma})}\left(U_{L}^{n+1}-U_{K}^{n+1}\right) \int_{t^{n}}^{t^{n+1}}\!\!\!\!\! \int_{T_{K,\sigma}\cap L}\!\!\!\!\!\!\!\!\!\!\! \nabla \psi(x,t) \cdot \mathbf{n}_{K,\sigma}\, dx \, dt.
\end{eqnarray*}
Now we prove that $B_{21}(\delta)-B_{210}(\delta) \rightarrow 0$ as $\delta \rightarrow 0$ and $B_{22}(\delta), \, B_{23}(\delta), \, B_{220}(\delta)\rightarrow 0$ as $\delta \rightarrow 0$.\\

\textbf{Estimate of $B_{21}(\delta)-B_{210}(\delta)$.} We have
\begin{equation*}
B_{21}(\delta)-B_{210}(\delta)=\sum_{n=0}^{N_{T}}\sum_{\substack{\sigma \in \mathcal{E}_{int}}} \!\!\!\! \text{m}(\sigma)r'(U^{n}_{K})\left[\int_{t^{n}}^{t^{n+1}}\!\!\!\! \left(\frac{\psi_{L}^{n}-\psi_{K}^{n}}{d_{\sigma}}-\frac{1}{\text{m}(T_{K,\sigma})}\int_{T_{K,\sigma}}\!\!\!\!\!\!\!\! \nabla\psi(x,t)\cdot \textbf{n}_{K,\sigma}\, dx\right)dt\right]\!\!.
\end{equation*}

Since the straight line $\overline{x_{K}x_{L}}$ is orthogonal to the edge $K|L$, we have $x_{L}-x_{K}=d_{\sigma}\mathbf{n}_{K,\sigma}$ and then from the regularity of $\psi$,
\begin{eqnarray*}
\frac{\psi_{L}^{n}-\psi_{K}^{n}}{d_{\sigma}}&=&\nabla \psi(x_{K},t^{n}) \cdot \mathbf{n}_{K,\sigma}+O(\Delta x)\\
&=& \nabla \psi(x,t) \cdot \mathbf{n}_{K,\sigma}+O(\delta), \,\ \forall (x,t) \in T_{K,\sigma} \times \left(t^{n},t^{n+1}\right).
\end{eqnarray*}
Then by taking the mean value over $T_{K,\sigma}$, there exists $D_{6}>0$ depending only on $\psi$ such that 
\begin{equation*}
\left\vert \int_{t^{n}}^{t^{n+1}}\left(\frac{\psi_{L}^{n}-\psi_{K}^{n}}{d_{\sigma}}-\frac{1}{\text{m}(T_{K,\sigma})}\int_{T_{K,\sigma}}\nabla \psi \cdot \mathbf{n}_{K,\sigma} \, dx \right)dt \right\vert \leq D_{6} \delta \Delta t,
\end{equation*}
and then 
\begin{equation*}
\left|B_{21}(\delta)-B_{210}(\delta)\right| \leq \delta D_{6} \sup_{s \in [m,M]}r'(s)\sum_{n=0}^{N_{T}}\Delta t\sum_{\substack{\sigma \in \mathcal{E}_{int}}}\text{m}(\sigma)\left|U_{L}^{n+1}-U_{K}^{n+1}\right|.
\end{equation*}
Since the straight line $\overline{x_{K}x_{L}}$ is orthogonal to the edge $\sigma=K|L$ for all $\sigma \in \mathcal{E}_{int,K}$ and the mesh is regular, there is a constant $D_{7}>0$ depending only on the dimension of the domain and the geometry of $\mathcal{T}$ such that  $\text{m}(\sigma)d_{\sigma} \leq D_{7} \text{m}(T_{K,\sigma})$ for all $K \in \mathcal{T}$ , all $\sigma \in \mathcal{E}_{ext,K}$ and then using the Cauchy-Schwarz inequality and the $L^{2}(0,T;H^{1})$ estimate (\ref{estiml2}), we obtain
\begin{equation*}
\left|B_{21}(\delta)-B_{210}(\delta)\right| \leq \delta D_{6} \sup_{s \in [m,M]}r'(s)\sqrt{D_{1}TD_{7}\text{m}(\Omega)} \longrightarrow 0 \text{ as } \delta \rightarrow 0.
\end{equation*}

\textbf{Estimate of $B_{22}(\delta)$.} Since $x \mapsto x\coth(x)$ is a 1-Lipschitz continuous function and is equal to 1 in 0, we have
\begin{eqnarray*}
\left|B_{22}(\delta)\right| &\leq & \sum_{n=0}^{N_{T}}\Delta t\sum_{\substack{\sigma \in \mathcal{E}_{int}}} \frac{\text{m}(\sigma)}{2}\left| q_{K,\sigma}\right| \left| U_{L}^{n+1}-U_{K}^{n+1}\right| \left| \psi_{L}^{n}-\psi_{K}^{n}\right|\\
& \leq & 2\delta \Vert \textbf{q} \Vert_{\infty}\sum_{n=0}^{N_{T}}\Delta t\sum_{\substack{\sigma \in \mathcal{E}_{int}}} \tau_{\sigma}\left| U_{L}^{n+1}-U_{K}^{n+1}\right| \left| \psi_{L}^{n}-\psi_{K}^{n}\right|, \text{ since $d_{\sigma} \leq 2 \delta$.}
\end{eqnarray*}
Then using the Cauchy-Schwarz inequality, the regularity of $\psi$ and the $L^{2}(0,T;H^{1})$ estimate (\ref{estiml2}), there exists $D_{8}>0$ only depending on $T$ and $\Omega$ such that:
\begin{equation*}
\left| B_{22}(\delta)\right| \leq \delta \Vert \textbf{q}\Vert_{\infty} D_{8} \Vert \psi \Vert_{\mathcal{C}^{1}} \sqrt{D_{1}} \longrightarrow 0 \text{ as } \delta \rightarrow 0.
\end{equation*}

\textbf{Estimate of $B_{23}(\delta)$.} Using Lemma \ref{propdr} and hypothesis (H4), we have
\begin{equation*}
\left| dr^{n}_{K,\sigma}-r'(U^{n}_{K})\right| \leq \sup_{s \in [m,M]}|r''(s)| \left|U_{L}^{n}-U^{n}_{K}\right|, \,\ \forall \sigma \in \mathcal{E}_{int}, \,\ \sigma=K|L.
\end{equation*}
Using the regularity of $\psi$ and the Cauchy-Schwarz inequality, we obtain
\begin{equation*}
\left| B_{23}(\delta) \right| \leq \delta \sup_{s \in [m,M]}|r''(s)| \Vert \psi \Vert_{\mathcal{C}^{1}} \sum_{n=0}^{N_{T}}\Delta t\sum_{\substack{\sigma \in \mathcal{E}_{int}}} \tau_{\sigma} \left|U_{L}^{n}-U^{n}_{K}\right| \left|U_{L}^{n+1}-U^{n+1}_{K}\right|,
\end{equation*}
and then using the $L^{2}(0,T;H^{1})$ estimate (\ref{estiml2}), we get
\begin{equation*}
\left| B_{23}(\delta) \right| \leq \delta \sup_{s \in [m,M]}|r''(s)| \Vert \psi \Vert_{\mathcal{C}^{1}} D_{1} \longrightarrow 0 \text{ as } \delta \rightarrow 0.
\end{equation*}

\textbf{Estimate of $B_{220}(\delta)$.} We obtain the same type of estimate as for $B_{23}(\delta)$:
\begin{equation*}
\left| B_{220}(\delta) \right| \leq 2\delta \sup_{s \in [m,M]}|r''(s)| \Vert \psi \Vert_{\mathcal{C}^{1}} D_{1} \longrightarrow 0 \text{ as } \delta \rightarrow 0.
\end{equation*}


\textbf{Estimate of $B_{3}(\delta)-B_{30}(\delta)$.} Using a discrete integration by parts, we obtain
\begin{equation*}
B_{3}(\delta) = -\sum_{n=0}^{N_{T}}\Delta t\sum_{\substack{\sigma \in \mathcal{E}_{int}}} \text{m}(\sigma)q_{K,\sigma}\frac{U_{K}^{n+1}+U_{L}^{n+1}}{2}\left(\psi_{L}^{n}-\psi_{K}^{n}\right),
\end{equation*}
and then we rewrite $B_{3}(\delta)$ as $B_{31}(\delta)+B_{32}(\delta)$, with
\begin{eqnarray*}
B_{31}(\delta)&=&-\sum_{n=0}^{N_{T}}\Delta t\sum_{\substack{\sigma \in \mathcal{E}_{int}}} \text{m}(\sigma)q_{K,\sigma}\frac{U_{L}^{n+1}-U_{K}^{n+1}}{2}\left(\psi_{L}^{n}-\psi_{K}^{n}\right),\\
B_{32}(\delta)&=& -\sum_{n=0}^{N_{T}}\Delta t\sum_{\substack{\sigma \in \mathcal{E}_{int}}} \text{m}(\sigma)q_{K,\sigma}U^{n+1}_{K}\left(\psi_{L}^{n}-\psi_{K}^{n}\right).
\end{eqnarray*}
Using the definition of $\nabla^{\delta}\psi$, we get
\begin{equation*}
B_{30}(\delta)=-\sum_{n=0}^{N_{T}}\sum_{\substack{\sigma \in \mathcal{E}_{int}}}\int_{t^{n}}^{t^{n+1}}\int_{T_{K,\sigma}}u_{\delta}(x,t)\frac{\text{m}(\sigma)}{\text{m}(T_{K,\sigma})}\left(\psi_{L}^{n}-\psi_{K}^{n}\right)\textbf{q}(x)\cdot \textbf{n}_{K,\sigma}\, dx \, dt,
\end{equation*}
which gives, using the definition of $u_{\delta}$, $B_{30}(\delta)=B_{310}(\delta)+B_{320}(\delta)$, where
\begin{eqnarray*}
B_{310}(\delta) &=& -\sum_{n=0}^{N_{T}}\Delta t\sum_{\substack{\sigma \in \mathcal{E}_{int}}}\text{m}(\sigma)\left(U^{n+1}_{L}-U^{n+1}_{K}\right)\left(\psi_{L}^{n}-\psi^{n}_{K}\right)\frac{1}{\text{m}(T_{K,\sigma})}\int_{T_{K,\sigma}\cap L}\textbf{q}(x)\cdot \textbf{n}_{K,\sigma}\, dx,\\
B_{320}(\delta) &= & -\sum_{n=0}^{N_{T}}\sum_{\substack{\sigma \in \mathcal{E}_{int}}}\text{m}(\sigma)U_{K}^{n+1}\left(\psi_{L}^{n}-\psi^{n}_{K}\right)\frac{1}{\text{m}(T_{K,\sigma})}\int_{T_{K,\sigma}}\textbf{q}(x)\cdot \textbf{n}_{K,\sigma}\, dx.
\end{eqnarray*}
Now we prove that $B_{32}(\delta)-B_{320}(\delta) \rightarrow 0$ as $\delta \rightarrow 0$ and $B_{31}(\delta), \, B_{310}(\delta)\rightarrow 0$ as $\delta \rightarrow 0$.\\
Using the regularity of $\textbf{q}$, there exists $D_{9}>0$ which does not depend on $\delta$ such that 
\begin{equation*}
\left| \frac{1}{\text{m}(\sigma)}\int_{\sigma}\textbf{q}(x)\cdot \textbf{n}_{K,\sigma} \, ds(x)-\frac{1}{\text{m}(T_{K,\sigma})}\int_{T_{K,\sigma}}\textbf{q}(x)\cdot \textbf{n}_{K,\sigma} \, dx\right| \leq D_{9} \delta.
\end{equation*}
Then we can estimate $B_{32}(\delta)-B_{320}(\delta)$:
\begin{eqnarray*}
\left| B_{32}(\delta)-B_{320}(\delta)\right| &\leq & \delta D_{9} M \sum_{n=0}^{N_{T}}\Delta t\sum_{\substack{\sigma \in \mathcal{E}_{int}}}\text{m}(\sigma) \left|\psi_{L}^{n}-\psi_{K}^{n}\right|\\
& \leq & \delta D_{8} D_{9} M \Vert \psi \Vert_{\mathcal{C}^{1}}\sqrt{D_{7}\text{m}(\Omega)} \longrightarrow 0 \text{ as } \delta \rightarrow 0.
\end{eqnarray*}
Moreover, we have
\begin{eqnarray*}
\left|B_{31}(\delta)\right| & \leq & \delta \Vert \textbf{q} \Vert_{\infty} \sum_{n=0}^{N_{T}}\Delta t\sum_{\substack{\sigma \in \mathcal{E}_{int}}}\tau_{\sigma}\left|U_{L}^{n+1}-U_{K}^{n+1}\right| \left|\psi_{L}^{n}-\psi_{K}^{n}\right|\\
& \leq & \delta \Vert \textbf{q} \Vert_{\infty} \Vert \psi \Vert_{\mathcal{C}^{1}}D_{8}\sqrt{D_{1}} \longrightarrow 0 \text{ as } \delta \rightarrow 0.
\end{eqnarray*}
We obtain in the same way that $B_{310}(\delta) \longrightarrow 0$ as $\delta \rightarrow 0$.\\

Hence $u$ satisfies
\begin{eqnarray*}
& & \int_{0}^{T}\int_{\Omega}\left(u(x,t)\, \pa_{t}\psi(x,t)+r'(u(x,t))\, \nabla u(x,t)\cdot \nabla\psi(x,t)+u(x,t)\, \mathbf{q}(x)\cdot \nabla\psi(x,t)\right)\, dx \, dt\\
& &+\int_{\Omega}u(x,0)\, \psi(x,0)\, dx=0,
\end{eqnarray*}
and then 
\begin{eqnarray*}
& & \int_{0}^{T}\int_{\Omega}\left(u(x,t)\, \pa_{t}\psi(x,t)+\nabla(r(u(x,t)))\cdot \nabla\psi(x,t)+u(x,t)\, \mathbf{q}(x)\cdot \nabla\psi(x,t)\right)\, dx \, dt\\
& &+\int_{\Omega}u(x,0)\, \psi(x,0)\, dx=0.
\end{eqnarray*}
It remains to show that $u-\overline{u} \in L^{\infty}(0,T;H^{1}_{0}(\Omega))$. This proof is based on the $L^{2}(0,T;H^{1}(\Omega))$ estimate (\ref{estiml2}) and is similar to the one of Theorem 5.1 in \cite{Chainais-Hillairet2003}.

It is proved in \cite{Carrillo2000} that the unique stationary solution of (\ref{PM}) is given by the Barenblatt-Pattle type formula
\begin{equation}
u^{eq}(x)=\left(C_{1}-\frac{\gamma -1}{2\gamma}|x|^{2}\right)_{+}^{1/(\gamma -1)},
\label{barenblatt}
\end{equation}
where $C_{1}$ is a constant such that $u^{eq}$ has the same mass as the initial data $u_{0}$.

while $V^{eq}$ satisfies the following elliptic problem
\begin{equation}
\left\{\begin{array}{ll} \Delta V^{eq}=g\left(\alpha_{N}+V^{eq}\right)-g\left(\alpha_{P}-V^{eq}\right)-C \text{   in } \Omega, &\\
V^{eq}(x)=\overline{V}(x) \text{ on } \Gamma^{D}, \quad \nabla V^{eq}\cdot \mathbf{n}=0 \text{ on } \Gamma^{N}.&\end{array}\right.
\label{eqV}
\end{equation}
The proof of the convergence to thermal equilibrium is based on an energy estimate with the control of the energy dissipation. More precisely, if we define 
\begin{equation}
H(s)=\int_{1}^{s}h(\tau)d\tau, \quad s \geq 0,
\label{H}
\end{equation}
then we can introduce the deviation of the total energy (sum of the internal energies for the electron and hole densities and the energy due to the electrostatic potential) from the thermal equilibrium (see \cite{Juengel1995a})
\begin{eqnarray}
\mathcal{E}(t)&=&\int_{\Omega}\left(\vphantom{\frac{1}{2}}H\left(N(t)\right)-H\left(N^{eq}\right)-h\left(N^{eq}\right)\left(N(t)-N^{eq}\right)+H\left(P(t)\right)-H\left(P^{eq}\right)\right. \nonumber\\
& & \quad \left. -h\left(P^{eq}\right)\left(P(t)-P^{eq}\right) +\frac{1}{2}\left\vert \nabla \left(V(t)-V^{eq}\right)\right\vert^{2}\right)dx,
\label{Econtinusc}
\end{eqnarray}
and the energy dissipation
\begin{equation}
\mathcal{I}(t)=-\int_{\Omega}\left(N(t)\left\vert \nabla(h(N(t))-V(t))\right\vert^{2}+P(t)\left\vert \nabla(h(P(t))+V(t))\right\vert^{2}\right)dx.
\label{Icontinusc}
\end{equation}
Then the keypoint of the proof is the following estimate:
\begin{equation}
0 \leq \mathcal{E}(t)+\int_{0}^{t}\mathcal{I}(\tau)\,d\tau \leq \mathcal{E}(0).
\label{inegentropie}
\end{equation}

Moreover, J. A. Carrillo and G. Toscani have proved in \cite{Carrillo2000} the convergence of the solution $u(x,t)$ of (\ref{pm}) to the Barenblatt-Pattle solution $u^{eq}(x)$ as $t \rightarrow \infty$. As in the case of the drift-diffusion model, the proof of the convergence to the Barenblatt-Pattle solution is based on an entropy estimate with the control of the entropy dissipation given by (\ref{inegentropie}), where the relative entropy is defined by
\begin{equation}
\mathcal{E}(t)=\int_{\mathbb{R}^{d}}\left(H(u(t))-H(u^{eq})+\frac{|x|^{2}}{2}\left(u(t)-u^{eq}\right)\right)dx,
\label{Econtinupm}
\end{equation}
where $H$ is defined by (\ref{H}) and the entropy dissipation is given by
\begin{equation}
\mathcal{I}(t)=-\frac{d}{dt}\mathcal{E}(t)=-\int_{\mathbb{R}^{d}}u(t)\left\vert \nabla\left(h(u(t))+\frac{|x|^{2}}{2}\right) \right\vert^{2}dx.
\label{Icontinupm}
\end{equation}

Moreover, we will consider Dirichlet-Neumann boundary conditions. The boundary $\pa \Omega=\Gamma$ is split into two parts $\Gamma=\Gamma^{D} \cup \Gamma^{N}$ and, if we denote by $\mathbf{n}$ the outward normal to $\Gamma$, the boundary conditions are Dirichlet boundary conditions on $\Gamma^{D}$
\begin{equation}
u(x,t)=\overline{u}(x,t) \text{ for } (x,t) \in \Gamma^{D} \times (0,T),
\label{BCD}
\end{equation}
and homogeneous Neumann boundary conditions on $\Gamma^{N}$:
\begin{equation}
\nabla r(u) \cdot \mathbf{n}=0 \text{ on } \Gamma^{N} \times (0,T).
\label{BCN}
\end{equation}

Moreover, if we suppose that the two following assumptions are fulfilled:
\begin{description}
\item[(H6)] $ \emph{div} (\mathbf{q})=0$,
\item[(H7)] there exist two constants $m>0$ and $M>0$ such that $m\leq \overline{u},u_{0}\leq M$,
\end{description}
then we have
\begin{equation}
0 <m \leq U^{n}_{K} \leq M, \quad \forall K \in \mathcal{T}, \quad \forall n \geq 0.
\label{estimlinf}
\end{equation}
\end{proposition}

Thus we obtain a scheme which leads only to solve a linear system of equations at each time step.\\
To sum up, our extension of the Scharfetter-Gummel flux is defined by
\begin{equation}
\mathcal{F}_{K,\sigma}^{n+1}=\left\{\begin{array}{lcl} \tau_{\sigma} dr_{K,\sigma}^{n} \left(B\left(\displaystyle{\frac{-d_{\sigma}q_{K,\sigma}}{dr_{K,\sigma}^{n}}}\right)U_{K}^{n+1}-B\left(\displaystyle{\frac{d_{\sigma}q_{K,\sigma}}{dr_{K,\sigma}^{n}}}\right)U_{L}^{n+1}\right), & & \forall \sigma=K|L \in \mathcal{E}_{K,int}, \\ \tau_{\sigma} dr_{K,\sigma}^{n} \left(B\left(\displaystyle{\frac{-d_{\sigma}q_{K,\sigma}}{dr_{K,\sigma}^{n}}}\right)U_{K}^{n+1}-B\left(\displaystyle{\frac{d_{\sigma}q_{K,\sigma}}{dr_{K,\sigma}^{n}}}\right)U_{\sigma}^{n+1}\right), & & \forall \sigma \in \mathcal{E}_{K,ext}^{D}, \\ 0, & & \forall \sigma \in \mathcal{E}_{K,ext}^{N},\end{array}\right.
\label{flux}
\end{equation}
where $dr_{K,\sigma}^{n}$ is defined by (\ref{dr3}). This flux preserves the equilibrium.

Motivation
Many numerical schemes have been proposed to approximate the solutions of nonlinear con\-vection-diffusion equations. In particular, finite volume methods have been proved to be efficient in the case of degenerate parabolic equations (see \cite{Eymard2000,Eymard2002}). We also mention the combined finite volume-finite element approach for nonlinear degenerate parabolic convection-diffusion-reaction equations analysed in \cite{Eymard2006a}. The definition of the so-called local Péclet upstream weighting numerical flux guarantees the stability of the scheme while reducing the excessive numerical diffusion added by the classical upwinding.\\
On the other hand, there exists a wide literature on numerical schemes for the drift-diffusion equations. It started with 1-D finite difference methods and the Scharfetter-Gummel scheme (\cite{Scharfetter1969}). In the linear pressure case ($r(s)=s$), a mixed exponential fitting finite element scheme has been successfully developed by F. Brezzi, L. Marini and P. Pietra in \cite{Brezzi1987,Brezzi1989}. The adaptation of the mixed exponential fitting method to the nonlinear case has been developed by F. Arimburgo, C. Baiocchi, L. Marini in \cite{Arimburgo1992} and by A. Jüngel in \cite{Juengel1995} for the one-dimensional problem, and by A. Jüngel and P. Pietra in \cite{Juengel1997} for the two-dimensional problem. Moreover, C. Chainais-Hillairet and Y.J. Peng proposed a finite volume scheme for the drift-diffusion equations in 1-D in \cite{Chainais-Hillairet2003a}, which was extended in \cite{Chainais-Hillairet2003,Chainais-Hillairet2004} in the multidimensional case. C. Chainais-Hillairet and F. Filbet also introduced in \cite{Chainais-Hillairet2007} a finite-volume scheme preserving the large time behavior of the solutions of the nonlinear drift-diffusion model.\\ 
Now to explain our approach, let us first recall some previous numerical results concerning the drift-diffusion system for semiconductors. The precise definitions of schemes considered will be presented in Section 2. We compare results obtained with three existing finite volume schemes: the classical upwind scheme proposed by C. Chainais-Hillairet and Y. J. Peng in \cite{Chainais-Hillairet2003a}, the Scharfetter-Gummel scheme introduced in \cite{Scharfetter1969} and the nonlinear upwind scheme studied in \cite{Chainais-Hillairet2007}.\\
In Figure \ref{comparelin}, we present some results obtained in the case of a linear diffusion ($r(s)=s$). We represent the relative energy $\mathcal{E}$ and the dissipation of energy $\mathcal{I}$ obtained with the upwind flux and the Scharfetter-Gummel flux for a test case in one space dimension. We can observe a phenomenon of saturation of $\mathcal{E}$ and $\mathcal{I}$ for the upwind flux. In addition, we clearly observe that the energy and its dissipation obtained with the Scharfetter-Gummel flux converge to zero when time goes to infinity, which means that densities $N(t)$ and $P(t)$ converge to the thermal equilibrium. It appears that the Scharfetter-Gummel flux is very efficient, but is only valid for linear diffusion. Moreover, we can emphasize that contrary to the upwind flux, the Scharfetter-Gummel flux preserves the thermal equilibrium.\\
In Figure \ref{comparenonlin}, we present numerical results obtained in the case of a nonlinear diffusion $r(s)=s^{2}$. We represent the relative energy $\mathcal{E}$ and the dissipation $\mathcal{I}$ obtained with the classical upwind flux and with the nonlinear upwind flux for a test case in one dimension of space. We still observe a phenomenon of saturation of $\mathcal{E}$ and $\mathcal{I}$ for the classical upwind flux. For the nonlinear flux, we clearly notice that the energy and its dissipation converge to zero when time goes to infinity.\\
Looking at these results, it seems crucial that the numerical flux preserves the thermal equilibrium to obtain the consistency of the approximate solution in the long time asymptotic limit.

